/* ============================================
   SECTION TITLE COMPONENT
   Heading with divider line, optional trailing content
   ============================================ */

@layer rift.tokens, rift.preset, rift.components;

@layer rift.components {

.ds-section-title {
  display: flex;
  align-items: baseline;
  gap: var(--gap-400);
  border-bottom: var(--border-025) solid var(--color-divider);
  padding-bottom: var(--padding-500);
}

/* Divider-less variant: for headings above content that draws its own
   lines, where a second rule would double up. The generous clearance
   the divider needed drops to a small breathing gap. */
.ds-section-title--no-divider {
  border-bottom: none;
  padding-bottom: var(--padding-400);
}

/* ============================================
   HEADING
   ============================================ */

.ds-section-title__heading {
  font-family: var(--font-heading-2-family);
  font-size: var(--font-heading-2-size);
  font-weight: var(--font-heading-2-weight);
  line-height: var(--font-heading-2-line-height);
  letter-spacing: var(--font-heading-2-letter-spacing);
  color: var(--color-text-secondary);
}

/* ============================================
   TRAILING CONTENT (count, badge, metadata)
   ============================================ */

.ds-section-title__trailing {
  font-family: var(--font-paragraph-family);
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  color: var(--color-text-tertiary);
}

/* Anchor: Heading's "#" link to the section, quiet until the heading is
   hovered or the link focused, and a scroll margin so a jump clears a
   sticky header (--ds-heading-scroll-margin, as on Heading). */
.ds-section-title__heading--anchored {
  scroll-margin-block-start: var(--ds-heading-scroll-margin, var(--gap-500));
}

.ds-section-title__anchor {
  margin-inline-start: 0.3em; /* ds-allow(typography): a word-space after the title at any tier, as on Heading */
  color: var(--color-text-tertiary);
  text-decoration: none;
  opacity: 0;
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard), color var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-section-title__heading:hover .ds-section-title__anchor,
.ds-section-title__anchor:focus-visible {
  opacity: 1;
}

.ds-section-title__anchor:hover {
  color: var(--color-text-secondary);
}

.ds-section-title__anchor:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
  border-radius: var(--radius-100);
}

@media (hover: none) {
  .ds-section-title__anchor {
    opacity: 1;
  }
}

} /* @layer rift.components */

import React from "react";
import { headingSlug } from "../../behaviors/headingSlug";
import "./SectionTitle.css";

/** Props owned by SectionTitle itself — everything else falls through to the root div. */
type SectionTitleOwnProps = {
  /**
   * Section heading text.
   * Note: this shadows the native `title` tooltip attribute, which SectionTitle does not expose.
   */
  title: string;
  /** Optional trailing content (count, badge, metadata) */
  trailing?: React.ReactNode;
  /** Whether to draw the bottom divider line. Set false above content that draws its own lines (bordered tables, calendars), so the section separates by whitespace alone. */
  divider?: boolean;
  /**
   * Give the heading an id and a "#" link to itself, shown on hover and
   * focus, as Heading's `anchor` does. `true` makes the id from the title;
   * a string sets it. The id lands on the heading, not the root, so an
   * `id` passed through goes to the root and the link targets the anchor.
   */
  anchor?: boolean | string;
  /** Accessible name of the anchor link, given the title. Defaults to "Link to <title>". */
  anchorLabel?: (title: string) => string;
  /** Additional CSS classes */
  className?: string;
};

export interface SectionTitleProps
  extends SectionTitleOwnProps,
    Omit<React.ComponentPropsWithoutRef<"div">, keyof SectionTitleOwnProps | "children"> {}

/**
 * SectionTitle — an `<h2>` section heading with optional trailing content
 * and a bottom divider, and with `anchor` a link to itself. Forwards a ref to the root div and spreads native
 * attributes onto it.
 */
export const SectionTitle = React.forwardRef<HTMLDivElement, SectionTitleProps>(
  ({ title, trailing, divider = true, anchor, anchorLabel = (text) => `Link to ${text}`, className, ...rest }, ref) => {
    const id = typeof anchor === "string" ? anchor : anchor ? headingSlug(title) || undefined : undefined;
    const classes = [
      "ds-section-title",
      !divider && "ds-section-title--no-divider",
      className,
    ]
      .filter(Boolean)
      .join(" ");

    return (
      <div {...rest} ref={ref} className={classes}>
        <h2 className={`ds-section-title__heading${id ? " ds-section-title__heading--anchored" : ""}`} id={id}>
          {title}
          {id && (
            <a className="ds-section-title__anchor" href={`#${id}`} aria-label={anchorLabel(title)}>
              #
            </a>
          )}
        </h2>
        {trailing !== undefined && trailing !== null && (
          <span className="ds-section-title__trailing">{trailing}</span>
        )}
      </div>
    );
  },
);

SectionTitle.displayName = "SectionTitle";
